                result[i][j] = test_in[3+i][j]
            elif test_in[9+i][j] != 0:  # r3
                result[i][j] = test_in[9+i][j]
            elif test_in[6+i][j] != 0:  # r2
                result[i][j] = test_in[6+i][j]
            else:
                result[i][j] = 0

    print(f"Test input:")
